class Solution {
    public int findClosestNumber(int[] nums) {
        Integer[] arr = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) arr[i] = nums[i];
        Arrays.sort(arr, (a, b) -> Math.abs(a) != Math.abs(b)
                ? Math.abs(a) - Math.abs(b)
                : b - a);
        return arr[0];
    }
}

